import{_ as p,a0 as l,w as o,s as d,I as t,x as n,a1 as a,A as i,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 上設置時間同步 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上設置時間同步 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上設置時間同步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上設置時間同步 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190805 How To Set Up Time Synchronization On Ubuntu","title":"如何在 Ubuntu 上設置時間同步","tag":"201908","desc":""},"relativePath":"201908/20190805 How To Set Up Time Synchronization On Ubuntu.md","filePath":"[post].md"}'),u={name:"201908/20190805 How To Set Up Time Synchronization On Ubuntu.md"};function r(h,s,g,m,b,k){const e=l("Link");return o(),d("div",null,[s[22]||(s[22]=t("h1",{id:"如何在-ubuntu-上設置時間同步",tabindex:"-1"},[n("如何在 Ubuntu 上設置時間同步 "),t("a",{class:"header-anchor",href:"#如何在-ubuntu-上設置時間同步","aria-label":"Permalink to “如何在 Ubuntu 上設置時間同步”"},"​")],-1)),s[23]||(s[23]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/13/135423xnk7zib00nn2aebv.jpg",alt:""})],-1)),t("p",null,[s[2]||(s[2]=n("你可能設置過 ",-1)),a(e,{href:"https://www.ostechnix.com/a-beginners-guide-to-cron-jobs/"},{default:i(()=>[...s[0]||(s[0]=[n("cron 任務",-1)])]),_:1}),s[3]||(s[3]=n(" 來在特定時間備份重要文件或執行系統相關任務。也許你配置了一個日誌服務器在特定時間間隔",-1)),a(e,{href:"https://www.ostechnix.com/manage-log-files-using-logrotate-linux/"},{default:i(()=>[...s[1]||(s[1]=[n("輪轉日誌",-1)])]),_:1}),s[4]||(s[4]=n("。但如果你的時鐘不同步，這些任務將無法按時執行。這就是要在 Linux 系統上設置正確的時區並保持時鐘與互聯網同步的原因。本指南介紹如何在 Ubuntu Linux 上設置時間同步。下面的步驟已經在 Ubuntu 18.04 上進行了測試，但是對於使用 systemd 的 ",-1)),s[5]||(s[5]=t("code",null,"timesyncd",-1)),s[6]||(s[6]=n(" 服務的其他基於 Ubuntu 的系統它們是相同的。",-1))]),s[24]||(s[24]=c(`<h3 id="在-ubuntu-上設置時間同步" tabindex="-1">在 Ubuntu 上設置時間同步 <a class="header-anchor" href="#在-ubuntu-上設置時間同步" aria-label="Permalink to “在 Ubuntu 上設置時間同步”">​</a></h3><p>通常，我們在安裝時設置時區。但是，你可以根據需要更改或設置不同的時區。</p><p>首先，讓我們使用 <code>date</code> 命令查看 Ubuntu 系統中的當前時區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tue Jul 30 11:47:39 UTC 2019</span></span></code></pre></div><p>如上所見，<code>date</code> 命令顯示實際日期和當前時間。這裏，我當前的時區是 <strong>UTC</strong>，代表<strong>協調世界時</strong>。</p><p>或者，你可以在 <code>/etc/timezone</code> 文件中查找當前時區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/timezone</span></span>
<span class="line"><span>UTC</span></span></code></pre></div><p>現在，讓我們看看時鐘是否與互聯網同步。只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Local time: Tue 2019-07-30 11:53:58 UTC</span></span>
<span class="line"><span>Universal time: Tue 2019-07-30 11:53:58 UTC</span></span>
<span class="line"><span>RTC time: Tue 2019-07-30 11:53:59</span></span>
<span class="line"><span>Time zone: Etc/UTC (UTC, +0000)</span></span>
<span class="line"><span>System clock synchronized: yes</span></span>
<span class="line"><span>systemd-timesyncd.service active: yes</span></span>
<span class="line"><span>RTC in local TZ: no</span></span></code></pre></div><p>如你所見，<code>timedatectl</code> 命令顯示本地時間、世界時、時區以及系統時鐘是否與互聯網服務器同步，以及 <code>systemd-timesyncd.service</code> 是處於活動狀態還是非活動狀態。就我而言，系統時鐘已與互聯網時間服務器同步。</p><p>如果時鐘不同步，你會看到下面截圖中顯示的 <code>System clock synchronized: no</code>。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/timedatectl-command-output-ubuntu.jpeg" alt=""></p><p><em>時間同步已禁用。</em></p><p>注意：上面的截圖是舊截圖。這就是你看到不同日期的原因。</p><p>如果你看到 <code>System clock synchronized:</code> 值設置為 <code>no</code>，那麼 <code>timesyncd</code> 服務可能處於非活動狀態。因此，只需重啓服務並看下是否正常。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart systemd-timesyncd.service</span></span></code></pre></div><p>現在檢查 <code>timesyncd</code> 服務狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status systemd-timesyncd.service</span></span>
<span class="line"><span>● systemd-timesyncd.service - Network Time Synchronization</span></span>
<span class="line"><span>Loaded: loaded (/lib/systemd/system/systemd-timesyncd.service; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>Active: active (running) since Tue 2019-07-30 10:50:18 UTC; 1h 11min ago</span></span>
<span class="line"><span>Docs: man:systemd-timesyncd.service(8)</span></span>
<span class="line"><span>Main PID: 498 (systemd-timesyn)</span></span>
<span class="line"><span>Status: &quot;Synchronized to time server [2001:67c:1560:8003::c7]:123 (ntp.ubuntu.com).&quot;</span></span>
<span class="line"><span>Tasks: 2 (limit: 2319)</span></span>
<span class="line"><span>CGroup: /system.slice/systemd-timesyncd.service</span></span>
<span class="line"><span>└─498 /lib/systemd/systemd-timesyncd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Jul 30 10:50:30 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:31 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:31 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:32 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:32 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:51:06 ubuntuserver systemd-timesyncd[498]: Synchronized to time server [2001:67c:1560:800</span></span></code></pre></div><p>如果此服務已啓用並處於活動狀態，那麼系統時鐘應與互聯網時間服務器同步。</p><p>你可以使用命令驗證是否啓用了時間同步：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span></code></pre></div><p>如果仍然不起作用，請運行以下命令以啓用時間同步：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo timedatectl set-ntp true</span></span></code></pre></div><p>現在，你的系統時鐘將與互聯網時間服務器同步。</p><h4 id="使用-timedatectl-命令更改時區" tabindex="-1">使用 timedatectl 命令更改時區 <a class="header-anchor" href="#使用-timedatectl-命令更改時區" aria-label="Permalink to “使用 timedatectl 命令更改時區”">​</a></h4><p>如果我想使用 UTC 以外的其他時區怎麼辦？這很容易！</p><p>首先，使用命令列出可用時區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl list-timezones</span></span></code></pre></div><p>你將看到類似於下圖的輸出。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/List-timezones-using-timedatectl-command.png" alt=""></p><p><em>使用 timedatectl 命令列出時區</em></p><p>你可以使用以下命令設置所需的時區（例如，Asia/Shanghai）：</p><p>（LCTT 譯註：本文原文使用印度時區作為示例，這裏為了便於使用，換為中國標準時區 CST。另外，在時區設置中，要注意 CST 這個縮寫會代表四個不同的時區，因此建議使用城市和 UTC+8 來説設置。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo timedatectl set-timezone Asia/Shanghai</span></span></code></pre></div><p>使用 <code>date</code> 命令再次檢查時區是否已真正更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date</span></span>
<span class="line"><span>Tue Jul 30 20:22:33 CST 2019</span></span></code></pre></div><p>或者，如果需要詳細輸出，請使用 <code>timedatectl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span>
<span class="line"><span>Local time: Tue 2019-07-30 20:22:35 CST</span></span>
<span class="line"><span>Universal time: Tue 2019-07-30 12:22:35 UTC</span></span>
<span class="line"><span>RTC time: Tue 2019-07-30 12:22:36</span></span>
<span class="line"><span>Time zone: Asia/Shanghai (CST, +0800)</span></span>
<span class="line"><span>System clock synchronized: yes</span></span>
<span class="line"><span>systemd-timesyncd.service active: yes</span></span>
<span class="line"><span>RTC in local TZ: no</span></span></code></pre></div><p>如你所見，我已將時區從 UTC 更改為 CST（中國標準時間）。</p><p>要切換回 UTC 時區，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo timedatectl set-timezone UTC</span></span></code></pre></div><h4 id="使用-tzdata-更改時區" tabindex="-1">使用 tzdata 更改時區 <a class="header-anchor" href="#使用-tzdata-更改時區" aria-label="Permalink to “使用 tzdata 更改時區”">​</a></h4><p>在較舊的 Ubuntu 版本中，沒有 <code>timedatectl</code> 命令。這種情況下，你可以使用 <code>tzdata</code>（Time zone data）來設置時間同步。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg-reconfigure tzdata</span></span></code></pre></div><p>選擇你居住的地理區域。對我而言，我選擇 <strong>Asia</strong>。選擇 OK，然後按回車鍵。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/configure-time-zone-using-tzdata-1.png" alt=""></p><p>接下來，選擇與你的時區對應的城市或地區。這裏，我選擇了 <strong>Kolkata</strong>（LCTT 譯註：中國用户請相應使用 Shanghai 等城市）。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/configure-time-zone-using-tzdata-2.png" alt=""></p><p>最後，你將在終端中看到類似下面的輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current default time zone: &#39;Asia/Shanghai&#39;</span></span>
<span class="line"><span>Local time is now: Tue Jul 30 21:59:25 CST 2019.</span></span>
<span class="line"><span>Universal Time is now: Tue Jul 30 13:59:25 UTC 2019.</span></span></code></pre></div><h4 id="在圖形模式下配置時區" tabindex="-1">在圖形模式下配置時區 <a class="header-anchor" href="#在圖形模式下配置時區" aria-label="Permalink to “在圖形模式下配置時區”">​</a></h4><p>有些用户可能對命令列方式不太滿意。如果你是其中之一，那麼你可以輕鬆地在圖形模式的系統設置面板中進行設置。</p><p>點擊 Super 鍵（Windows 鍵），在 Ubuntu dash 中輸入 <strong>settings</strong>，然後點擊設置圖標。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/System-settings-Ubuntu-dash.png" alt=""></p><p><em>從 Ubuntu dash 啓動系統的設置</em></p><p>或者，單擊位於 Ubuntu 桌面右上角的向下箭頭，然後單擊左上角的“設置”圖標。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Ubuntu-system-settings.png" alt=""></p><p><em>從頂部面板啓動系統的設置</em></p><p>在下一個窗口中，選擇“細節”，然後單擊“日期與時間”選項。打開“自動的日期與時間”和“自動的時區”。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Set-automatic-timezone-in-ubuntu.png" alt=""></p><p><em>在 Ubuntu 中設置自動時區</em></p><p>關閉設置窗口就行了！你的系統始終應該與互聯網時間服務器同步了。</p><hr>`,67)),t("p",null,[s[8]||(s[8]=n("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-set-up-time-synchronization-on-ubuntu/"},{default:i(()=>[...s[7]||(s[7]=[n("https://www.ostechnix.com/how-to-set-up-time-synchronization-on-ubuntu/",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=n("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[9]||(s[9]=[n("sk",-1)])]),_:1}),s[14]||(s[14]=n(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[10]||(s[10]=[n("lujun9972",-1)])]),_:1}),s[15]||(s[15]=n(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[11]||(s[11]=[n("geekpi",-1)])]),_:1}),s[16]||(s[16]=n(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[12]||(s[12]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[n("Linux中國",-1)])]),_:1}),s[21]||(s[21]=n(" 榮譽推出",-1))])])}const C=p(u,[["render",r]]);export{T as __pageData,C as default};
